DebugRsrcName not 'ckid';	#endif	include kDialogRsrcName not 'ckid';	include kGeneralRsrcName not 'ckid';	include kPrintingRsrcName not 'ckid';#endif // !THINK_Rez//--------------------------------------------------------------------------------------------------// CONSTANTS//--------------------------------------------------------------------------------------------------#ifndef __Outline_r_h__#include "Outline.r.h"#endif// Finder Information// ------------------#if !defined(THINK_Rez) && !defined(MW_Rez)#define kApplicationName	$$Shell("XAppName")#else#define kApplicationName	TARGET_APPLICATION_NAME#endif // !THINK_Rez//--------------------------------------------------------------------------------------------------// RESOURCES FOR MENUS//--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// Menu Bars//--------------------------------------------------------------------------------------------------resource 'MBAR' (kMBarDisplayed,#if qNames"Outline MBAR",#endif	purgeable) {	{ mApple; mFile; mEdit; mOutlineMenu }};//--------------------------------------------------------------------------------------------------// Menus//--------------------------------------------------------------------------------------------------include kDefaultRsrcName 'CMNU' (mApple);	// Grab the default Apple menusinclude kDefaultRsrcName 'CMNU' (mFile);		// Grab the default File menusinclude kDefaultRsrcName 'CMNU' (mEdit);		// Grab the default Edit menuresource 'CMNU' (mOutlineMenu,#if qNames"Outline Menu",#endifnonpurgeable) {	mOutlineMenu,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"OutlineMenu",	 {	/* array: 3 elements *//* [1] */	"Command Handled By Application",noIcon, "1", noMark, plain, cCommandHandledByApplication;/* [2] */	"Command Handled By Document", noIcon, "2", noMark, plain, cCommandHandledByDocument;/* [3] */	"Command Handled By View",	noIcon, "3", noMark, plain, cCommandHandledByView;	  }	};resource 'CMNU' (mBuzzwords,#if qNames"Buzzwords",#endifpurgeable) {	mBuzzwords,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"Buzzwords",	 {	/* array: 13 elements */		"Page Setup Change",	noIcon,	noKey,	noMark, plain, cChangePrinterStyle;		"Typing",				noIcon,	noKey,	noMark,	plain, cTyping;		"Tracker Command",		noIcon,	noKey,	noMark, plain, cTrackerCommand;	}};//--------------------------------------------------------------------------------------------------// Balloon Help Resources for Menus//--------------------------------------------------------------------------------------------------// Includes resource 'STR#' (kStandardHelpStrings, "Balloon Help String 1")// with our application name substituted in strings#include "HelpStrings.r"#if !qCarboninclude kDefaultRsrcName  'hmnu' (mFile);include kDefaultRsrcName  'hmnu' (mEdit);resource 'STR#' (kOutlineMenuHelp, purgeable) {	{		"No help yet for this  item",		"Help For Menu Title",		"Help For First Menu Item",		"Help For Second Menu Item",		"Help For Third Menu Item",	}};resource 'hmnu' (mOutlineMenu){	HelpMgrVersion,	hmDefaultOptions,	0, // balloon definition function	0, // variation code	// Missing items	HMStringResItem	{		kOutlineMenuHelp,1,		kOutlineMenuHelp,1,		kOutlineMenuHelp,1,		kOutlineMenuHelp,1,	},	// Title and items	{		// Title		HMStringResItem		{			kOutlineMenuHelp,2,			kOutlineMenuHelp,2,			kOutlineMenuHelp,2,			kOutlineMenuHelp,2,		},		// First Item		HMStringResItem		{			kOutlineMenuHelp,3,			kOutlineMenuHelp,3,			kOutlineMenuHelp,3,			kOutlineMenuHelp,3,		},		// Second Item		HMStringResItem		{			kOutlineMenuHelp,4,			kOutlineMenuHelp,4,			kOutlineMenuHelp,4,			kOutlineMenuHelp,4,		},		// Third Item		HMStringResItem		{			kOutlineMenuHelp,5,			kOutlineMenuHelp,5,			kOutlineMenuHelp,5,			kOutlineMenuHelp,5,		},	}};#endif // !qCarbon//--------------------------------------------------------------------------------------------------// RESOURCES FOR VIEWS, DIALOGS, ALERTS etc.//--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// About Box//--------------------------------------------------------------------------------------------------resource 'DITL' (phAboutApp,#if qNames"phAboutApp",#endif	purgeable) {	 {	/* array DITLarray: 3 elements */		/* [1] */		{167, 288, 187, 348},		Button {			enabled,			"OK"		};		/* [2] */		{10, 75, 154, 348},		StaticText {			disabled,			"This sample program demonstrates a scriptable outline view."			"\n"			WRITTEN_WITH_MACAPP		};		/* [3] */		{10, 20, 42, 52},		Icon {			disabled,			noteIcon		}	}};include kDefaultRsrcName  'ALRT' (phAboutApp);		// Grab the default about box#if !defined(THINK_Rez) && !defined(MW_Rez)include "OutlineTerminology.rsrc"	'aete' (0);#endifinclude kDefaultRsrcName  'STR#' (kDefaultCredits);	// Grab the default credits//--------------------------------------------------------------------------------------------------// MultiFinder™ information//--------------------------------------------------------------------------------------------------/* Additional size deltas to be added to partition size */#if qNames#define kNamesSizeDelta 75#else#define kNamesSizeDelta 0#endif#if qDebug#define kDebugSizeDelta 0#else#define kDebugSizeDelta 0#endif#define kModelFarSizeDelta 0#ifndef MW_Rez					// MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	notStationeryAware,	reserved,	reserved,	reserved,	reserved,	/* Suggested partition size */	(1000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,	/* Minimum partition size */	(800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif // !MW_Rez//--------------------------------------------------------------------------------------------------// Icons//--------------------------------------------------------------------------------------------------resource 'ICN#' (kApplicationID,#if qNames"Outline Application",#endif	purgeable) {	{	/* array: 2 elements */		/* [1] */		$"0000 0000 0000 0000 0000 0000 0000 0000"		$"00FF 00FE 0081 8102 0180 8203 0100 C403"		$"0300 4803 0240 5003 0660 2003 0450 0003"		$"0C48 0003 0844 0003 1842 0003 1044 0003"		$"3048 0003 2050 0003 6060 0003 4040 0003"		$"C000 0003 8000 0003 FFFF FFFF 7FFF FFFF"		$"7FFF FFFF",		/* [2] */		$"0000 0000 0000 0000 0000 0000 0000 0000"		$"00FF 00FE 00FF 81FE 01FF 83FF 01FF C7FF"		$"03FF CFFF 03FF DFFF 07FF FFFF 07FF FFFF"		$"0FFF FFFF 0FFF FFFF 1FFF FFFF 1FFF FFFF"		$"3FFF FFFF 3FFF FFFF 7FFF FFFF 7FFF FFFF"		$"FFFF FFFF FFFF FFFF FFFF FFFF 7FFF FFFF"		$"7FFF FFFF"	}};resource 'ics#' (kApplicationID,#if qNames"Outline Application",#endif	purgeable) {	{	/* array: 2 elements */		/* [1] */		$"0000 0000 0F9F 18B1 18E1 3C41 2A01 6B01"		$"4E01 CC01 8001 FFFF FFFF",		/* [2] */		$"0000 0000 0F9F 1FBF 1FFF 3FFF 3FFF 7FFF"		$"7FFF FFFF FFFF FFFF FFFF"	}};resource 'ics4' (kApplicationID,#if qNames"Outline Application",#endif	purgeable) {	$"0000 0000 0000 0000 0000 0000 0000 0000"	$"0000 7777 7006 7776 0007 7777 7067 777D"	$"0007 F777 7677 777D 0077 FF77 7777 777D"	$"0077 FCF7 7777 777D 0777 FCFF 7777 777D"	$"0777 FFFC 7777 777D 7777 FFC7 7777 777D"	$"7777 7C77 7777 777D DDDD DDDD DDDD DDDD"	$"DDDD DDDD DDDD DDDD"};resource 'ics8' (kApplicationID,#if qNames"Outline Application",#endif	purgeable