ocumentID);		// MacApp Document large black & whiteinclude kDefaultRsrcName  'ics#' (kDocumentID);		// MacApp Document small black & whiteinclude kDefaultRsrcName  'ics4' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics8' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'icl4' (kDocumentID);		// MacApp Document large 4 bitinclude kDefaultRsrcName  'icl8' (kDocumentID);		// MacApp Document large 8 bitinclude kDefaultRsrcName  'ICN#' (kStationeryID);	// MacApp Stationery large black & whiteinclude kDefaultRsrcName  'ics#' (kStationeryID);	// MacApp Stationery small black & whiteinclude kDefaultRsrcName  'ics4' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'ics8' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'icl4' (kStationeryID);	// MacApp Stationery large 4 bitinclude kDefaultRsrcName  'icl8' (kStationeryID);	// MacApp Stationery large 8 bit//--------------------------------------------------------------------------------------------------// Memory usage information for Outline//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefs… Oh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable) {	"Outline, "APPLE_LONG_COPYRIGHT};resource 'FREF' (kApplicationID,#if qNames"Outline Application",#endif	purgeable) {	'APPL',	0,	""};resource 'FREF' (kDocumentID,#if qNames"Outline Document",#endif	purgeable) {	kFileType,	1,	""};resource 'FREF' (kStationeryID,#if qNames"Outline Stationery",#endif	purgeable) {	kStationery,	2,	""};resource 'BNDL' (kBundleID,#if qNames"Outline",#endif	purgeable) {	kSignature,	0,	{ /* array TypeArray: 2 elements */		/* [1] */		'ICN#',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		},		/* [2] */		'FREF',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		}	}};//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x01,	development,	0x01,	verUs,	"1.1d1",	"Outline 1.1d1, ©Apple Computer, Inc. 1988-97"};include kDefaultRsrcName  'vers' (2);		// Overall package//--------------------------------------------------------------------------------------------------// End of Outline.r